{
  "additionalProperties": false,
  "$schema": "http://json-schema.org/schema#",
  "type": "object",
  "properties": {
    "firstName": {
      "type": "string",
      "description": "The first name of the User."
    },
    "lastName": {
      "type": "string",
      "description": "The last name of the User."
    },
    "emailAddress": {
      "type": "string",
      "description": "The email address of the User."
    },
    "name": {
      "$ref": "type.schema.json#/properties/name"
    },
    "checksum": {
      "$ref": "type.schema.json#/properties/checksum"
    },
    "title": {
      "type": "string",
      "description": "The title of the user."
    },
    "birthDate": {
      "type": "number",
      "description": "The birth date of the User"
    },
    "desc": {
      "$ref": "type.schema.json#/properties/desc"
    }
  },
  "required": [
    "name",
    "desc",
    "emailAddress",
    "firstName",
    "lastName"
  ]
}
